import{_ as o,r as n,o as p,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Layouts - October CMS - 4.x","titleTemplate":false,"description":"Define the scaffold for your website pages.","frontmatter":{"subtitle":"Define the scaffold for your website pages."},"headers":[{"level":2,"title":"Using a Dynamic Page Title","slug":"using-a-dynamic-page-title","link":"#using-a-dynamic-page-title","children":[]},{"level":2,"title":"Placeholders","slug":"placeholders","link":"#placeholders","children":[]},{"level":2,"title":"Dynamic Layouts","slug":"dynamic-layouts","link":"#dynamic-layouts","children":[{"level":3,"title":"Layout Execution Life Cycle","slug":"layout-execution-life-cycle","link":"#layout-execution-life-cycle","children":[]},{"level":3,"title":"Method and Variable Access","slug":"method-and-variable-access","link":"#method-and-variable-access","children":[]},{"level":3,"title":"Priority Layouts","slug":"priority-layouts","link":"#priority-layouts","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"4.x/cms/themes/layouts.md","filePath":"4.x/cms/themes/layouts.md"}'),u={name:"4.x/cms/themes/layouts.md"};function r(d,a,g,k,h,m){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Layouts",-1)),s(e),a[1]||(a[1]=i(`<p>Layouts define a common scaffold for your pages, which usually means everything that repeats on every page, such as a header and a footer. They will almost always contain HTML code such as HEAD, TITLE and BODY tags.</p><p>Layout template files reside in the <strong>layouts</strong> directory in your theme. Layout template files should have the <strong>htm</strong> extension. Inside the layout file you should use the <code>{% page %}</code> tag to output the page content. Next is an example of the simplest possible layout.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block aside"><p>Remember that if you refer a layout from a subdirectory you should specify the subdirectory name.</p></div><p>To use a layout for a <a href="./pages.html">page</a>, the page should refer the layout file name (without extension) in the configuration section. Below is an example page template using the <strong>default.htm</strong> layout.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>When this page is requested its content is merged with the layout, or more precisely - the layout&#39;s <code>{% page %}</code> tag is replaced with the page content. The previous examples would generate the following markup:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Note that you can <a href="./partials.html">render partials</a> in layouts. This lets you to share the common markup elements between different layouts. For example, you can have a partial that outputs the website CSS and JavaScript links. This approach simplifies the resource management - if you want to add a JavaScript reference you should modify a single partial instead of editing all the layouts.</p><p>The configuration section is optional for layouts. The supported configuration parameters are <strong>name</strong> and <strong>description</strong>. The parameters are optional and used in the back-end user interface. Example layout template with a description:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Basic layout example</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="using-a-dynamic-page-title"><a href="#using-a-dynamic-page-title" class="header-anchor">#</a> Using a Dynamic Page Title</h2><p>The <code>meta_title</code> and <code>meta_description</code> properties of a <a href="./pages.html">page</a> support parsing variables from the page life cycle. The following layout template will set the page title based on the value of the active page.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span>{{ this.page.meta_title }} - October CMS<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        {% page %}
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The page template can then define its title using Twig-like variable syntax using values that are available in the global environment, in this case the <strong>post.title</strong> value is used.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
<span class="token key attr-name">meta_title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ post.title }} - Blog</span>&quot;</span>
</code></pre></div><blockquote><p><strong>Note</strong>: Only basic Twig variables are supported. Filters, tags and functions cannot be used.</p></blockquote><h2 id="placeholders"><a href="#placeholders" class="header-anchor">#</a> Placeholders</h2><p>Placeholders allow pages to inject content to the layout. Placeholders are defined in the layout templates with the <code>{% placeholder %}</code> tag. The next example shows a layout template with a placeholder <strong>head</strong> defined in the HTML HEAD section.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> head <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Pages can inject content to placeholders with the <code>{% put %}</code> and <code>{% endput %}</code> tags. The following example demonstrates a simple page template which injects a CSS link to the placeholder <strong>head</strong> defined in the previous example.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/my-page</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> head <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/themes/demo/assets/css/page.css<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The page content goes here.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>More information on placeholders can be found <a href="./../markup/tag-placeholder.html">in the Markup guide</a>.</p><h2 id="dynamic-layouts"><a href="#dynamic-layouts" class="header-anchor">#</a> Dynamic Layouts</h2><p>Layouts, like pages, can use any Twig features. Please refer to the <a href="./pages.html">Dynamic Pages section</a> of the documentation for details.</p><h3 id="layout-execution-life-cycle"><a href="#layout-execution-life-cycle" class="header-anchor">#</a> Layout Execution Life Cycle</h3><p>Inside the layout&#39;s PHP section you can define the following functions for handling the page execution life cycle: <code>onInit</code>, <code>onStart</code>, <code>onBeforePageStart</code> and <code>onEnd</code>.</p><p>The <code>onInit</code> function is executed when all components are initialized and before AJAX requests are handled. The <code>onStart</code> function is executed in the beginning of the page processing. The <code>onBeforePageStart</code> function is executed after the layout <a href="./components.html">components</a> ran, but before the page&#39;s <code>onStart</code> function is executed. The <code>onEnd</code> function is executed after the page is rendered. The sequence the handlers are executed is following:</p><ol><li>Layout <code>onInit()</code> function.</li><li>Page <code>onInit()</code> function.</li><li>Layout <code>onStart()</code> function.</li><li>Layout components <code>onRun()</code> method.</li><li>Layout <code>onBeforePageStart()</code> function.</li><li>Page <code>onStart()</code> function.</li><li>Page components <code>onRun()</code> method.</li><li>Page <code>onEnd()</code> function.</li><li>Layout <code>onEnd()</code> function.</li></ol><h3 id="method-and-variable-access"><a href="#method-and-variable-access" class="header-anchor">#</a> Method and Variable Access</h3><p>The nearest context is used when accessing variables and methods inside partials, pages and layouts. Take the following <a href="./themes.html">PHP code section</a> definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;myVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">function</span> <span class="token function-definition function">myMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In the above example, accessing <code>myVariable</code> or <code>this.myMethod()</code> inside Twig will check the existence in the following order:</p><ol><li>Partial</li><li>Page</li><li>Layout</li></ol><h3 id="priority-layouts"><a href="#priority-layouts" class="header-anchor">#</a> Priority Layouts</h3><p>Layouts can specify an <code>is_priority</code> attribute in their settings to activate priority mode. In normal circumstances, the layout contents render after the page contents. This allows the page to manipulate layout properties, like the title or meta description. Visually the order looks like this.</p><div class="language-text extra-class"><pre class="language-text"><code>Layout (3) ← Page (1) → Partials (2)
</code></pre></div><p>In priority mode, the layout uses a more natural load order where the <code>{% page %}</code> tag renders inline with the layout contents. However, there is no support for placeholders when using this mode. The priority layout load order looks more like this.</p><div class="language-text extra-class"><pre class="language-text"><code>Layout (1) → Page (2) → Partials (3)
</code></pre></div><p>This is particularly useful when <a href="./../resources/building-apis.html">building API endpoints</a>. In the following example, the page logic will not run since the page tag is never called.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">API Layout</span>&quot;</span>
<span class="token key attr-name">is_priority</span> <span class="token punctuation">=</span> <span class="token value attr-value">1</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> <span class="token boolean">false</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/page.html">Page Twig Tag</a></li></ul></div>`,43))])}const v=o(u,[["render",r]]);export{f as __pageData,v as default};
